    private const string Prefix = "D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/RarePriorFiniteMonitor.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "RarePriorFiniteMonitor", H("RarePriorFiniteMonitor"), Blocks(
                Paragraph(Text("The monitor begins with the first paid Read. Its only count register is Fin 376 with saturation at 375. The block is six alpha bits followed by ten beta bits; the suffix is beta alpha, beta beta alpha alpha. An independent prefix grammar establishes exact whole-word recognition. The finite block position, suffix position, accepted state and sink hold no history.")),
                Paragraph(Text("Runtime is the original FiniteFields together with the monitor and one-shot mode. Every transaction first calls the original partial finiteStep. The legal-history projection keeps original Counts and payloadReturns in the source rather than in the observer. Third-write activation follows the original marker writer and bare snapshot latch.")),
                Paragraph(Text("G alpha completes; G beta enters Gbeta. Gbeta beta completes; Gbeta alpha executes the original return and disables special operation permanently. Seeds, early phases and other legal histories use the ordinary query row. Pending permits only matching Stop, and delivered permits neither Read nor Stop. Off-permission matrix rows grant no terminal Read.")),
                Node("whole-word-recognition", "whole_word_recognition", "whole word recognition", "The prefix invariant distinguishes complete blocks, incomplete blocks, suffix positions and the sink. Acceptance is equivalent to a complete word with at least 375 blocks."),
                Node("runtime-projection", "runtime_projection", "runtime projection", "Projecting every partial runtime execution to FiniteFields gives the original finite execution, including failures."),
                Node("arbitrary-legal-projection", "arbitrary_legal_projection", "arbitrary legal projection", "Original native prefix reconstruction identifies the finite fields for every legal paid operation history. Source counters remain external."),
                Node("query-mode-classification", "query_mode_classification", "query mode classification", "A special query requires its matching fourth-segment phase and one-shot mode. All other finite configurations use the ordinary row."),
                Node("original-latch-activation", "original_latch_activation", "original latch activation", "The five-letter suffix prefix has no snapshot. The sixth original Read performs the third marker write and latches the snapshot before G becomes active."),
                Node("special-transactions", "special_transactions", "special transactions", "The four original active transitions give the two special completions, the Gbeta continuation and the return that selects ordinary mode."),
                Node("terminal-permissions", "terminal_permissions", "terminal permissions", "Pending admits exactly its matching Stop. Pending and delivered reject every Read; delivered also rejects every Stop."),
                Node("exhaustive-history-modes", "exhaustive_history_modes", "exhaustive history modes", "The history invariant restricts G and Gbeta to the recognized whole word and its single beta continuation. Every other successful history queries the ordinary row."),
                Node("special-return-permanence", "special_return_permanence", "special return permanence", "Ordinary mode is invariant under every subsequent successful transaction, including the suffix after the original Gbeta alpha return."))));

